<?php

declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_role('ADMIN');$q=trim((string)($_GET['q']??''));$action=trim((string)($_GET['action']??''));$entity=trim((string)($_GET['entity']??''));$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$logs=admin_activity_logs(compact('q','action','entity','from','to'));$options=admin_activity_filter_options();$pageTitle='Activity Logs';$bodyClass='portal-page';require __DIR__.'/../includes/header.php';
?>
<div class="portal-shell"><?php require __DIR__.'/../includes/sidebar.php';?><main class="portal-main"><header class="portal-page-header"><div><span class="eyebrow">AUDIT TRAIL</span><h1 class="mt-2 mb-1">Activity Logs</h1><p class="text-muted mb-0">Review security and operational actions recorded across Franscoffee Shop.</p></div></header><section class="portal-card inventory-filter-card"><form method="get" class="activity-filter-grid"><div><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="User, email, action, IP"></div><div><label class="form-label">Action</label><select class="form-select" name="action"><option value="">All actions</option><?php foreach($options['actions'] as $a):?><option value="<?=e($a)?>" <?=$action===$a?'selected':''?>><?=e($a)?></option><?php endforeach;?></select></div><div><label class="form-label">Entity</label><select class="form-select" name="entity"><option value="">All entities</option><?php foreach($options['entities'] as $e):?><option value="<?=e($e)?>" <?=$entity===$e?'selected':''?>><?=e($e)?></option><?php endforeach;?></select></div><div><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="inventory-filter-actions"><button class="btn btn-coffee">Apply</button><a class="btn btn-outline-secondary" href="<?=url('admin/activity-logs.php')?>">Reset</a></div></form></section><section class="portal-card mt-4"><div class="panel-heading"><div><span class="eyebrow">RECENT ACTIVITY</span><h2><?=count($logs)?> record<?=count($logs)===1?'':'s'?></h2></div><small class="text-muted">Showing up to 500 newest matches</small></div><?php if(!$logs):?><div class="empty-state compact"><i class="bi bi-clock-history"></i><h3>No activity found</h3><p>Try changing the filters.</p></div><?php else:?><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Date / Time</th><th>User</th><th>Action</th><th>Target</th><th>IP</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $log):$details=$log['details_json']?json_decode((string)$log['details_json'],true):null;?><tr><td><strong><?=e(date('M j, Y',strtotime($log['created_at'])))?></strong><small class="d-block text-muted"><?=e(date('g:i:s A',strtotime($log['created_at'])))?></small></td><td><?php if($log['user_id']):?><strong><?=e(trim(($log['first_name']??'').' '.($log['last_name']??'')))?></strong><small class="d-block text-muted"><?=e($log['email']??'')?> · <?=e($log['role']??'')?></small><?php else:?><span class="text-muted">System / guest</span><?php endif;?></td><td><span class="activity-action"><?=e($log['action'])?></span></td><td><?=e($log['entity_type']?:'—')?><?=!empty($log['entity_id'])?' #'.(int)$log['entity_id']:''?></td><td><code><?=e($log['ip_address']?:'—')?></code></td><td><?php if(is_array($details)&&$details):?><details class="activity-details"><summary>View</summary><pre><?=e(json_encode($details,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre></details><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main></div><?php require __DIR__.'/../includes/footer.php';?>
